# %% ../../nbs/04_pipelines.summarizer.ipynb #b70b6558
class Summarizer:
    def __init__(
        self,
        llm,
        prompt_template: Optional[str] = None,              
        map_prompt: Optional[str] = None,
        reduce_prompt: Optional[str] = None,
        refine_prompt: Optional[str] = None, 
        **kwargs,
    ):
        """
        `Summarizer` summarizes one or more documents

        **Args:**

        - *llm*: An `onprem.LLM` object
        - *prompt_template*: A model specific prompt_template with a single placeholder named "{prompt}".
                             All prompts (e.g., Map-Reduce prompts) are wrapped within this prompt.
                             If supplied, overrides the `prompt_template` supplied to the `LLM` constructor.
        - *map_prompt*: Map prompt for Map-Reduce summarization. If None, default is used.
        - *reduce_prompt*: Reduce prompt for Map-Reduce summarization. If None, default is used.
        - *refine_prompt*: Refine prompt for Refine-based summarization. If None, default is used.

        """
        self.llm = llm
        self.prompt_template = prompt_template if prompt_template is not None else llm.prompt_template
        self.map_prompt = map_prompt if map_prompt else DEFAULT_MAP_PROMPT
        self.reduce_prompt = reduce_prompt if reduce_prompt else DEFAULT_REDUCE_PROMPT
        self.refine_base_prompt = DEFAULT_BASE_REFINE_PROMPT
        self.refine_prompt = refine_prompt if refine_prompt else DEFAULT_REFINE_PROMPT


    def summarize(self, 
                  fpath:str=None, #  path to either a folder of documents or a single file
                  strategy:str='map_reduce', # One of {'map_reduce', 'refine'}
                  chunk_size:int=1000, # Number of characters of each chunk to summarize
                  chunk_overlap:int=0, # Number of characters that overlap between chunks
                  token_max:int=2000, # Maximum number of tokens to group documents into
                  max_chunks_to_use: Optional[int] = None, # Maximum number of chunks (starting from beginning) to use
                  raw_text:str=None, # Optional: raw text to process (skips file loading)
                 ):
        """
        Summarize one or more documents (e.g., PDFs, MS Word, MS Powerpoint, plain text)
        using either Langchain's Map-Reduce strategy or Refine strategy.
        The `max_chunks` parameter may be useful for documents that have abstracts or informative introductions. 
        If `max_chunks=None`, all chunks are considered for summarizer.
        
        Args:
            fpath: Path to file or directory 
            strategy: Summarization strategy ('map_reduce' or 'refine')
            chunk_size: Characters per chunk
            chunk_overlap: Character overlap between chunks  
            token_max: Maximum tokens to group documents into
            max_chunks_to_use: Maximum chunks to process
            raw_text: Raw text to process (skips file loading)
            
        Note: Provide exactly one of: fpath or raw_text
        """
        
        # Input validation - exactly one of fpath or raw_text must be provided
        input_count = sum([fpath is not None, raw_text is not None])
        if input_count != 1:
            raise ValueError("Provide exactly one of: fpath or raw_text")
        
        # Handle different input types
        if raw_text is not None:
            # Create Document object from raw text
            from langchain_core.documents import Document
            docs = [Document(page_content=raw_text, metadata={'source': 'raw_text'})]
        else:
            # Original file path behavior
            if os.path.isfile(fpath):
                docs = load_single_document(fpath)
            else:
                docs = load_documents(fpath)
            if not docs:
                raise Exception(f'Could not load text from document: {fpath}')

        if strategy == 'map_reduce':
            summary = self._map_reduce(docs, 
                                      chunk_size=chunk_size, 
                                      chunk_overlap=chunk_overlap, 
                                      token_max=token_max,
                                      max_chunks_to_use=max_chunks_to_use)
        elif strategy == 'refine':
            summary = self._refine(docs, 
                                   chunk_size=chunk_size, 
                                   chunk_overlap=chunk_overlap, 
                                   token_max=token_max,
                                   max_chunks_to_use=max_chunks_to_use)
            
        else:
            raise ValueError(f'Unknown strategy: {self.strategy}')
        return summary

    
    def _wrap(self, template: str) -> str:
        """Wrap a prompt template in the model's prompt_template (if set)."""
        if self.prompt_template:
            return format_string(self.prompt_template, prompt=template)
        return template

    def _count_tokens(self, text: str) -> int:
        """
        Estimate the number of tokens in `text`. Uses the backend's tokenizer
        when available (LlamaCpp/HFPipeline expose `get_num_tokens`); otherwise
        falls back to a ~4-chars-per-token approximation (adequate for the
        `token_max` grouping heuristic, and works for all backends).
        """
        backend = getattr(self.llm, 'llm', None)
        if backend is not None and hasattr(backend, 'get_num_tokens'):
            try:
                return backend.get_num_tokens(text)
            except Exception:
                pass
        return max(1, len(text) // 4)

    def _split_text(self, text: str, chunk_size: int, chunk_overlap: int) -> List[str]:
        """Split `text` into character-based chunks with optional overlap."""
        if chunk_size <= 0:
            return [text]
        chunks = []
        start = 0
        n = len(text)
        step = max(1, chunk_size - chunk_overlap)
        while start < n:
            chunks.append(text[start:start + chunk_size])
            start += step
        return chunks

    def _split_documents(self, docs, chunk_size: int, chunk_overlap: int) -> List[str]:
        """Split a list of Documents into a flat list of text chunks."""
        chunks = []
        for d in docs:
            content = d.page_content if hasattr(d, 'page_content') else str(d)
            chunks.extend(self._split_text(content, chunk_size, chunk_overlap))
        return chunks

    def _map_reduce(self, docs, chunk_size=1000, chunk_overlap=0, token_max=1000,
                    max_chunks_to_use=None, **kwargs):
        """
        Map-Reduce summarization (LangChain-free).

        - Map: summarize each chunk with `map_prompt`.
        - Reduce: iteratively group the chunk summaries so each group stays under
          `token_max`, summarize each group with `reduce_prompt`, and repeat until
          a single summary remains.
        """
        split_docs = self._split_documents(docs, chunk_size, chunk_overlap)
        if max_chunks_to_use:
            split_docs = split_docs[:max_chunks_to_use]

        map_template = self._wrap(self.map_prompt)
        reduce_template = self._wrap(self.reduce_prompt)

        # --- Map: summarize each chunk ---
        summaries = []
        for chunk in split_docs:
            prompt = format_string(map_template, docs=chunk)
            summaries.append(self.llm.prompt(prompt).strip())

        # --- Reduce: iteratively collapse until a single summary remains ---
        while len(summaries) > 1:
            groups = self._group_by_token_max(summaries, token_max)
            # if everything fits in one group, this is the final reduce
            new_summaries = []
            for group in groups:
                combined = "\n\n".join(group)
                prompt = format_string(reduce_template, docs=combined)
                new_summaries.append(self.llm.prompt(prompt).strip())
            # guard against no progress (single oversized item)
            if len(new_summaries) >= len(summaries):
                combined = "\n\n".join(summaries)
                prompt = format_string(reduce_template, docs=combined)
                summaries = [self.llm.prompt(prompt).strip()]
                break
            summaries = new_summaries

        output_text = summaries[0] if summaries else ""
        return {'input_documents': split_docs, 'output_text': output_text}

    def _group_by_token_max(self, summaries: List[str], token_max: int) -> List[List[str]]:
        """Group consecutive summaries so each group's combined text is <= token_max."""
        groups = []
        current = []
        current_tokens = 0
        for s in summaries:
            s_tokens = self._count_tokens(s)
            if current and current_tokens + s_tokens > token_max:
                groups.append(current)
                current = [s]
                current_tokens = s_tokens
            else:
                current.append(s)
                current_tokens += s_tokens
        if current:
            groups.append(current)
        return groups

    def _refine(self, docs, chunk_size=1000, chunk_overlap=0,
                max_chunks_to_use=None, **kwargs):
        """
        Refine summarization (LangChain-free).

        Summarize the first chunk with `refine_base_prompt`, then iteratively
        refine that summary with each subsequent chunk using `refine_prompt`
        (which has `{existing_answer}` and `{text}` placeholders).
        """
        base_template = self._wrap(self.refine_base_prompt)
        refine_template = self._wrap(self.refine_prompt)

        split_docs = self._split_documents(docs, chunk_size, chunk_overlap)
        if max_chunks_to_use:
            split_docs = split_docs[:max_chunks_to_use]

        if not split_docs:
            return ""

        # initial summary from the first chunk
        summary = self.llm.prompt(format_string(base_template, text=split_docs[0])).strip()

        # refine with each subsequent chunk
        for chunk in split_docs[1:]:
            prompt = format_string(refine_template, existing_answer=summary, text=chunk)
            summary = self.llm.prompt(prompt).strip()

        return summary

        
    def summarize_by_concept(self,
                            fpath=None, # path to file, raw text, or list of pre-chunked text
                            concept_description:str=None, # Summaries are generated with respect to the described concept.
                            similarity_threshold:float=0.0, # Minimum similarity for consideration. Tip: Increase this when using similarity_method="senttransform" to mitigate hallucination. A value of 0.0 is sufficient for TF-IDF or should be kept near-zero.
                            max_chunks:int=4, # Only this many snippets above similarity_threshold are considered.
                            similarity_method:str="tfidf", # One of "senttransform" (sentence-transformer embeddings) or "tfidf" (TF-IDF)
                            summary_prompt:str = TARGET_PROMPT, # The prompt used for summarization. Should have exactly two variables, {concept_description} and {text}.
                            raw_text:str=None, # Optional: raw text to process (skips file loading)
                            chunks:list=None, # Optional: pre-chunked text as list (skips both file loading and chunking)
                            ):
        """
        Summarize document with respect to concept described by `concept_description`. Returns a tuple of the form (summary, sources).
        
        Args:
            fpath: Path to file 
            concept_description: The concept to focus summarization on
            similarity_threshold: Minimum similarity score for chunk consideration
            max_chunks: Maximum number of chunks to use for summarization
            similarity_method: "tfidf" or "senttransform"
            summary_prompt: Template for summarization prompt
            raw_text: Raw text to process (skips file loading)
            chunks: Pre-chunked text as list (skips file loading and chunking)
            
        Note: Provide exactly one of: fpath, raw_text, or chunks
        """
        if similarity_method not in ['tfidf', 'senttransform']:
            raise ValueError('similarity_method must be one of {"tifidf", "senttransform"}')
        
        # Input validation - exactly one of fpath, raw_text, or chunks must be provided
        input_count = sum([fpath is not None, raw_text is not None, chunks is not None])
        if input_count != 1:
            raise ValueError("Provide exactly one of: fpath, raw_text, or chunks")
        
        # Handle different input types
        if chunks is not None:
            # Use pre-chunked text directly
            pass
        else:
            # Get content from either file or raw text
            if raw_text is not None:
                content = raw_text
            else:
                # Original file path behavior
                if not os.path.isfile(fpath):
                    raise ValueError(f"{fpath} is not a file.")
                docs = load_single_document(fpath)
                if not docs:
                    raise Exception(f'Could not load text from document: {fpath}')
                ext = "." + fpath.rsplit(".", 1)[-1].lower()
                content = '\n\n'.join([doc.page_content for doc in docs])
            
            # Chunk the content
            paragraphs = segment(content, maxchars=2000, unit="paragraph")
            # Combine paragraphs if very short (i.e. a header)
            chunks = []
            text = ""
            count = 0 
            max_combine = 2
            for p in paragraphs:
                text += f"\n\n{p}" 
                count += 1
                if count == max_combine+1 or len(text)>100:
                    chunks.append(text)
                    count = 0 
                    text = ""
            
            # Remove duplicate chunks
            chunks = list(set(chunks))
            
        # TF-IDF method to find relevant sections of the documents
        if similarity_method=="tfidf":
            from sklearn.feature_extraction.text import TfidfVectorizer
            from sklearn.metrics.pairwise import cosine_similarity
            vectorizer = TfidfVectorizer(
                            ngram_range=(1,5),
                            stop_words="english",
                            max_features=10000,
                            min_df=0.,
                            max_df=0.95,
                        )
        
            result = vectorizer.fit_transform([concept_description] + chunks)
            cos = cosine_similarity(result[0:1], result).flatten()

            direct_word_chunks = {}
            for index, c in enumerate(chunks):
                if cos[index+1] <= similarity_threshold: continue
                update_c = {
                    "chunk": c, 
                    "index": index, 
                    "cosSim": cos[index+1],
                }
                direct_word_chunks[index] = update_c
                
                
        # Sentence Transformer method to find relevant sections of the documents
        elif similarity_method=="senttransform":
            
            from sentence_transformers import SentenceTransformer, util
            # Sentence transformer model
            k = None # Optional parameter to restrict number
            st_model = SentenceTransformer(self.llm.embedding_model_name)
            chunk_embedding = st_model.encode(chunks, convert_to_tensor=True)
            phrase_embedding = st_model.encode(concept_description, convert_to_tensor=True)
            top_k = k if k is not None else chunk_embedding.shape[0]
            cos_scores = util.pytorch_cos_sim(phrase_embedding, chunk_embedding)[0]
            # sort cosine similarity scores
            try:
                top_results = np.argpartition(-cos_scores.cpu(), range(top_k))[0:top_k]
            except:
                top_results = np.argpartition(-cos_scores, range(top_k))[0:top_k]
        
            # Get the best chunks of text 
            direct_word_chunks = {}
            for index, c in enumerate(chunks):
                score = float(cos_scores[index].cpu())
                if score <= similarity_threshold: continue
                update_c = {
                    "chunk": c,
                    "index": index,
                    "cosSim": score
                }
                direct_word_chunks[index] = update_c
            
        # Sort the list of chunks by the cosine similarity
        sorted_chunks = sorted(
            direct_word_chunks.items(), 
            key=lambda x:x[1]["cosSim"],
            reverse=True
        )

        # Select the chunks (with relevant surrounding chunks)    
        selected_ids = [s[0] for s in sorted_chunks[0:max_chunks]]
        
        # Get the text to use
        target_text = ""
        for ids in selected_ids: 
            target_text += f"{chunks[ids].strip()}\n"
            
        # prompt the LLM to summarize energy parts 
        response = ""
        if target_text: 
            response = self.llm.prompt(summary_prompt.format(**{"text": target_text, 
                                                                "concept_description":concept_description}))
        else:
            response = f'No text relevant to "{concept_description}" in document.'
        return response, sorted_chunks[:max_chunks]

